INSERT INTO `faq` (`id`, `question`, `answer`, `service_id`, `department_id`, `keywords`, `sort_order`, `status`, `created_by`, `created_at`, `updated_at`) VALUES
(1, 'كيف أتواصل مع المرشد الأكاديمي؟', 'يمكنك التواصل مع مرشدك الأكاديمي عبر البريد الإلكتروني المسجل في ملفك الشخصي، أو زيارة مكتبه في أوقات الدوام الرسمي.', NULL, 1, 'مرشد، أكاديمي، تواصل', 1, 'published', 1, '2026-04-16 09:33:29', '2026-04-16 09:33:29'),
(2, 'ما هي مواعيد دوام عمادة شؤون الطلاب؟', 'أوقات الدوام من الأحد إلى الخميس من الساعة 8 صباحاً حتى الساعة 4 مساءً.', NULL, NULL, 'دوام، مواعيد، عمادة', 2, 'published', 1, '2026-04-16 09:33:29', '2026-04-16 09:33:29'),
(3, 'كيف أقدم طلب دعم مالي؟', 'يمكنك تقديم طلب الدعم المالي عبر منصة شؤون الطلاب، واختيار خدمة \"طلب الدعم المالي\" وتعبئة النموذج المطلوب.', NULL, NULL, 'دعم مالي، طلب، صندوق', 3, 'published', 1, '2026-04-16 09:33:29', '2026-04-16 09:33:29'),
(5, 'ما هي خدمات ذوي الإعاقة المتوفرة؟', 'تشمل الخدمات: التسهيلات في الاختبارات، والدعم الأكاديمي، والتجهيزات الخاصة، ويمكن التقدم من خلال وحدة ذوي الإعاقة.', NULL, 3, 'إعاقة، خدمات، تسهيلات', 5, 'published', 1, '2026-04-16 09:33:29', '2026-04-16 09:33:29'),
(6, 'كيف أسجل في نادٍ طلابي؟', 'ادخل على صفحة الأندية الطلابية في المنصة، اختر النادي المناسب وقدم طلب الانضمام مع استيفاء الشروط المطلوبة.', NULL, 5, 'نادي طلاب، الأندية، نادي', 0, 'published', 1, '2026-04-16 14:07:33', '2026-04-16 14:07:33');

