INSERT INTO `knowledge_base` (`id`, `title`, `content`, `type`, `related_id`, `service_id`, `department_id`, `keywords`, `status`, `created_by`, `created_at`, `updated_at`) VALUES
(1, 'معلومات عامة عن عمادة شؤون الطلاب', 'عمادة شؤون الطلاب هي الجهة المسؤولة عن متابعة الشؤون الطلابية خارج نطاق الأنشطة الأكاديمية، وتقديم الخدمات والبرامج التي تُسهم في تنمية الطالب اجتماعياً ونفسياً وثقافياً وترفيهياً، وتسعى العمادة لتحقيق بيئة جامعية داعمة ومحفزة.', 'info', NULL, NULL, NULL, 'عمادة، شؤون طلاب، خدمات', 'published', 1, '2026-04-16 09:33:29', '2026-04-17 11:44:04'),
(2, 'أوقات الدوام الرسمي', 'يعمل موظفو عمادة شؤون الطلاب خلال الدوام الرسمي من الأحد إلى الخميس، من الساعة الثامنة صباحاً حتى الرابعة مساءً. خلال إجازة الصيف يكون الدوام من الثامنة صباحاً حتى الثانية والنصف مساءً.', 'info', NULL, NULL, NULL, 'دوام، مواعيد، ساعات العمل', 'published', 1, '2026-04-16 09:33:29', '2026-04-17 11:43:54'),
(3, 'ماهو برنامج إليت', 'أن يكون برنامج إليت - جامعة بيشة مرجعًا أكاديميًا رائدًا لاكتشاف ورعاية وتمكين الموهوبين والمتفوقين في مختلف المجالات، ليصبحوا قادة فكر وابتكار يسهمون في خدمة الوطن وتحقيق رؤية المملكة 2030.\r\n\r\nمن خلال تقديم بيئة جامعية محفزة تدعم الطلاب المتميزين:\r\n\r\nبرامج إثرائية (أكاديمية ومجتمعية)\r\nدعم مالي (مكافأة مستقطعة من صندوق الطلاب)\r\nإشراف أكاديمي متخصص\r\nفرص محلية ودولية (مؤتمرات، مسابقات، برامج تبادل)\r\nبما يضمن تعزيز قدراتهم وتحويل طاقاتهم إلى إنجازات ملموسة تخدم الجامعة والمجتمع والوطن.', 'info', NULL, NULL, 2, '', 'published', 1, '2026-04-16 13:32:30', '2026-04-16 13:32:30'),
(4, 'الدعم المادي لبرنامج إليت', 'الشروط:\r\nشرط الحفاظ على معدل تراكمي لا يقل عن 4.5/5\r\nحضور ما لا يقل عن 80% من الأنشطة\r\nالمشاركة في مشروع أو إنجاز واحد على الأقل سنوياً\r\nالمخالفة = إنذار + إيقاف الدعم في حالة التكرار\r\n\r\nالآلية:\r\n\r\nدعم مالي مستقطع من صندوق الطلاب\r\nبرامج إثرائية (ورش عمل، معسكرات، مؤتمرات)\r\nدعم المشاركة في المسابقات المحلية والدولية\r\nتوفر مرافق خاصة (مختبرات، قاعات تدريب)\r\nإشراف أكاديمي فردي لكل طالب', 'info', NULL, NULL, 2, 'دعم مادي، برنامج إليت، موهوبين، مكافئة', 'published', 1, '2026-04-16 13:54:46', '2026-04-16 13:54:46'),
(5, 'ما هو موعد صرف المكافئة', 'تُصرف مكافآت طلاب جامعة بيشة شهرياً بانتظام، ويتم إيداعها عادة في تاريخ 23 من كل شهر ميلادي  او في نهاية الشهر الميلادي، مع إمكانية تقديم الموعد في المناسبات الوطنية. تتضمن أيضاً مكافآت تميز وبدل كتب، ويمكن الاستفسار عن حالتها عبر بوابة الطالب بـجامعة بيشة أو منصة إيليت للطلاب المتميزين. تعادل المكافئة الشهرية 900 ريال شهرياً', 'faq', NULL, NULL, NULL, 'المكافئة ، مكافئة، المكافأة، مكافئة', 'published', 1, '2026-04-16 13:58:57', '2026-04-16 13:58:57'),
(6, 'كيف أسجل في نادٍ طلابي؟', 'س: كيف أسجل في نادٍ طلابي؟\nج: ادخل على صفحة الأندية الطلابية في المنصة، اختر النادي المناسب وقدم طلب الانضمام مع استيفاء الشروط المطلوبة.', 'faq', 6, NULL, 5, 'نادي طلاب، الأندية، نادي', 'published', 1, '2026-04-16 14:07:33', '2026-04-16 14:07:33'),
(7, 'نموذج طلب الدعم النفسي', 'نموذج طلب الدعم النفسي\nنموذج تقديم طلب للحصول على الإرشاد والدعم النفسي\nلتحميل هذا النموذج: [نموذج طلب الدعم النفسي](/STD/assets/uploads/forms/file_69e0c54e6e5a14.93639356.png)', 'form', 1, 1, 1, '', 'published', 1, '2026-04-16 14:17:34', '2026-04-16 14:17:34'),
(13, 'دليل الأندية الطلابية', 'دليل الأندية الطلابية\nالأندية المتاحة وشروط الانضمام والأنشطة\nلتحميل هذا الدليل: [دليل الأندية الطلابية](/STD/assets/uploads/guides/file_69e1f20ef0b994.20262819.pdf)', 'guide', 3, 3, 5, '', 'published', 2, '2026-04-17 12:00:18', '2026-04-17 12:00:18'),
(15, 'شكوى', 'تمكنك من تقديم شكوى لاي من العقوبات التي تواجهها\n\n\n', 'service', 6, NULL, NULL, 'شكوى، شكاوي', 'published', 1, '2026-04-17 12:59:38', '2026-04-17 12:59:38'),
(16, 'اقتراح', 'يمكنك تقديم اقتراحاتك بما يتعلق بعمادة شؤون الطلاب\n\n\n', 'service', 7, NULL, NULL, 'اقتراح، الاقتراحات، مقترح', 'published', 1, '2026-04-17 13:00:17', '2026-04-17 13:00:29'),
(17, 'استفسار', 'يمكنك تقديم استفسارك فيما يتعلق بعمادة شؤون الطلاب\n\n\n', 'service', 8, NULL, NULL, '', 'published', 1, '2026-04-17 13:01:09', '2026-04-17 13:01:09'),
(18, 'طلب الدعم المالي', 'تقديم طلبات الدعم والمساعدات المالية من صندوق الطالب\nإثبات الحاجة المادية، معدل لا يقل عن 2.5\nكشف الحساب البنكي، شهادة دخل العائلة\nتعبئة النموذج ثم رفع المستندات ثم الانتظار للمراجعة والقبول', 'service', 4, NULL, 4, 'مالي، دعم، مساعدة مالية، صندوق', 'published', 1, '2026-04-17 13:01:38', '2026-04-17 13:01:38'),
(19, 'برنامج التطوع في عمادة شئون الطلاب', 'يمكن للطلاب الأنضمام الى برنامج التطوع من خلال الحضور شخصياً الى مقر العمادة وتقديم الطلب. \r\nويتضمن برنامج التطوع عدة مهام تطوعية مثل: \r\nالأشراف على الفعاليات \r\nتنظيم الفعاليات \r\nالاشراف على كافتيريا الجامعة \r\nالتعامل مع الطلاب الدوليين\r\nالاشراف على الاندية الطلابية', 'info', NULL, NULL, NULL, 'تطوع، برنامج التطوع، متطوعين، التطوع', 'published', 1, '2026-04-19 05:23:50', '2026-04-19 05:23:50'),
(20, 'خدمة طلب صرف مكافئة تفوق', 'يتم صرف مكافئة قدرها 1000 ريال للطالب المتفوق\n1- معدل تراكمي 4.5 من 5 على الأقل\r\n2- عدم وجود اي متعثرات ومواد رسوب\n1- كشف السجل الاكاديمي\r\n2- شهادة بنكية\nيتم التقديم من خلال الخدمة الالكترونية و الحضور للعمادة', 'service', 9, NULL, 2, 'مكافئة تفوق، تفوق ، المكافئة', 'published', 1, '2026-04-19 05:26:01', '2026-04-19 05:26:01');

