INSERT INTO `knowledge_chunks` (`id`, `knowledge_id`, `chunk_text`, `chunk_order`, `embedding_json`, `embedding_model`, `created_at`) VALUES
(1, 3, 'أن يكون برنامج إليت - جامعة بيشة مرجعًا أكاديميًا رائدًا لاكتشاف ورعاية وتمكين الموهوبين والمتفوقين في مختلف المجالات، ليصبحوا قادة فكر وابتكار يسهمون في خدمة الوطن وتحقيق رؤية المملكة 2030.\r\n\r\nمن خلال تقديم بيئة جامعية محفزة تدعم الطلاب المتميزين:\r\n\r\nبرامج إثرائية (أكاديمية ومجتمعية)\r\nدعم مالي (مكافأة مستقطعة من صندوق الطلاب)\r\nإشراف أكاديمي متخصص\r\nفرص محلية ودولية (مؤتمرات، مسابقات، برامج تبادل)\r\nبما يضمن تعزيز قدراتهم وتحويل طاقاتهم إلى إنجازات ملموسة تخدم الجامعة والمجتمع والوطن.', 0, '[0.0078712255,0.03041683,-0.002782842,0.011748324,-0.0047599166,0.005711271,-0.014422112,-0.0017616401,-0.0032955739,-0.041784257,-0.027344415,0.012302564,0.0021861773,0.018732263,-0.0070181014,-0.0057887416,-0.008938524,0.0037873893,-0.03071882,0.011089403,0.024235807,-0.0059715807,0.007914939,-0.00800735,-0.01692939,-0.011459737,-0.0010753792,0.030094204,-0.026948407,0.12067351,-0.0051438096,3.6475816e-5,0.005783482,0.008224313,-0.0050075636,0.014016974,0.0024026548,-0.013368059,0.013748662,-0.0053170007,0.002672145,0.02038457,0.013081089,0.008934555,0.012758086,0.004866435,0.01641331,-0.0072616725,0.0125238355,0.014275867,0.00019833057,0.0087475665,0.011918607,-0.022844521,-0.005874717,0.019718135,0.006504247,-0.009003893,0.024472123,0.05567635,0.0038395238,0.013959735,0.012653339,0.0047268914,0.010327271,0.026070273,0.006308065,-0.009267444,-0.0072331936,-0.013409607,-0.0031912962,0.022646507,-0.0005328551,-0.011141032,0.0011723222,-0.02127029,-0.02227195,-0.009345276,-0.015195637,-0.004411928,0.020094011,-0.021042552,0.006211657,-0.0152467415,0.009561873,0.021301903,0.0014221212,0.00067042245,-0.012240121,0.016231606,-0.018625176,0.011695874,-0.01138275,0.007072026,-0.00816393,0.0022726203,-0.0016611206,0.016445989,0.005268422,0.008064701,-0.010377401,-0.0032154892,0.047204223,-0.016207399,0.022721238,0.0068742707,0.01795688,0.003516478,0.01939573,0.015245744,-0.008921139,-0.16420747,-0.009965164,0.018067174,-0.0041653365,-0.042306878,-0.020102184,-0.00