(2, 4, 'الشروط:\r\nشرط الحفاظ على معدل تراكمي لا يقل عن 4.5/5\r\nحضور ما لا يقل عن 80% من الأنشطة\r\nالمشاركة في مشروع أو إنجاز واحد على الأقل سنوياً\r\nالمخالفة = إنذار + إيقاف الدعم في حالة التكرار\r\n\r\nالآلية:\r\n\r\nدعم مالي مستقطع من صندوق الطلاب\r\nبرامج إثرائية (ورش عمل، معسكرات، مؤتمرات)\r\nدعم المشاركة في المسابقات المحلية والدولية\r\nتوفر مرافق خاصة (مختبرات، قاعات تدريب)\r\nإشراف أكاديمي فردي لكل طالب', 0, '[-0.0070311325,0.02686461,0.005373215,0.0012526094,-0.0073305853,0.010720885,0.008559389,0.0026385228,-0.0127690295,-0.045806833,-0.017697942,0.018508181,-0.019831613,-0.0016635424,-0.022707857,-0.02533842,0.0034011474,-0.0025541254,-0.032667883,0.016361328,-0.0058784694,0.004704031,0.020889757,0.0036720315,-0.019783549,0.012626403,0.0005173259,-0.002715202,-0.016564853,0.12815797,0.0074684233,-0.0107829105,0.009914601,0.0018996324,0.0035520722,0.008418508,-0.002188365,-0.024585094,-0.009052687,-0.0020552587,-0.004044213,0.0048508714,0.02519583,0.002032281,-0.0005949387,-0.00575029,0.015637543,0.004602457,0.00019335751,0.0032060237,0.009746819,0.01163331,0.0051750354,0.00386226,-0.00022799692,0.020756034,8.5234075e-5,0.018369615,0.037409358,0.021623084,-0.0026842258,0.004850707,0.011097248,-0.0006763146,0.006743321,0.0035351384,0.039487246,-0.011874926,-0.0024541786,0.0052110488,-0.009526318,0.027529942,0.006080523,0.005191476,0.0069129746,-0.00065656984,0.009582387,-0.017126046,0.0009204316,0.018150533,-0.003513408,-0.015276126,0.023441017,-0.024428612,0.011605549,0.05147241,0.007827676,0.0038436034,0.0035560685,0.0132704135,-0.012164649,0.021382106,-0.0010736752,0.006655568,-0.010207938,0.002955703,-0.0014597515,0.006280439,0.012699778,0.001421432,0.0041356497,-0.009497895,0.03432533,-0.022287609,0.01715867,0.0081987465,-0.0038990716,0.007204125,0.02162677,0.016003994,0.004176725,-0.17001434,-0.0019758581,0.015778728,-0.00021112307,-0.041782793,-0.00610768,-0.003466343,0.02338931,0.028091488,-0.0008724864,0.028605888,-0.006648457,0.0101431,-0.01319