(3, 5, 'تُصرف مكافآت طلاب جامعة بيشة شهرياً بانتظام، ويتم إيداعها عادة في تاريخ 23 من كل شهر ميلادي  او في نهاية الشهر الميلادي، مع إمكانية تقديم الموعد في المناسبات الوطنية. تتضمن أيضاً مكافآت تميز وبدل كتب، ويمكن الاستفسار عن حالتها عبر بوابة الطالب بـجامعة بيشة أو منصة إيليت للطلاب المتميزين. تعادل المكافئة الشهرية 900 ريال شهرياً', 0, '[0.012045322,0.012419959,0.007113817,-0.0003370544,0.013819136,-0.027973618,-0.014370603,-0.0060404553,0.011965883,-0.04834972,-0.009947896,0.006291456,0.0077825305,0.003172414,-0.023766186,0.009394988,-0.020475797,-0.005295563,-0.0065062568,-0.0032441237,0.024643516,0.019577576,0.0054787495,-0.026868034,-0.019650906,-0.012195468,-0.003007507,0.012670481,-0.0013397437,0.11225488,0.0061491323,-0.009948765,-0.024048474,-0.017247302,-0.008091658,0.009887816,-0.007948602,0.008715375,-0.0032079082,0.0007899461,0.011476186,0.0037251802,-0.0050474443,0.0100757,0.0013164193,0.0018912613,0.0260888,-0.008204255,0.002301388,0.022764964,0.0010346443,0.0143457,0.016192049,-0.0031892585,-0.0056666345,0.030417623,-0.008641317,-0.012920102,0.02758474,0.036174584,0.010204148,-0.019579394,0.026436763,-0.011465565,0.030722607,0.0073894574,-0.007989581,0.0050624693,0.005700205,-0.008678634,-0.007815223,0.021508712,0.0017707668,0.021183308,0.013508233,-0.022034451,-0.018263867,0.0062547154,0.0056751263,0.03379044,-0.0014810611,-0.02646736,-0.01117761,0.0049840882,0.0027743087,0.00663131,-0.0013471494,-0.012982036,-0.013794217,-0.0032577252,-0.0335053,0.0066385707,-0.010146399,0.00039345928,-0.013722855,-0.027707411,0.002834847,0.03807558,-0.0008488462,0.028616251,-0.017288374,0.002294164,0.027363613,-0.014895673,0.03564615,0.03001877,0.0050222753,0.025863606,0.014042991,0.0031317063,0.014766612,-0.15821606,-0.0004341658,0.016760854,0.03008233,-0.04210424,-0.015788138,-0.0034098807,0.0124866245,0.017738163,0.0070205163,0.003317643,-0.022278953,0.0019326289,-0.031467598,0.02319288,0.011646826,-0.0027705966,0.013820421,0.043219443,0.018379891,-0.00642201